import{_ as s,C as n,o as r,c as i,aj as e,G as o}from"./chunks/framework.BwH0p-pt.js";const f=JSON.parse('{"title":"Magic AI — Platforms","description":"","frontmatter":{},"headers":[],"relativePath":"3.0/magic-ai/platforms.md","filePath":"3.0/magic-ai/platforms.md","lastUpdated":1788942616000}'),l={name:"3.0/magic-ai/platforms.md"};function d(p,t,m,h,g,c){const a=n("ImagePopup");return r(),i("div",null,[t[0]||(t[0]=e('<h1 id="magic-ai-—-platforms" tabindex="-1">Magic AI — Platforms <a class="header-anchor" href="#magic-ai-—-platforms" aria-label="Permalink to &quot;Magic AI — Platforms&quot;">​</a></h1><blockquote><p><strong>Sidebar:</strong> Magic AI → <strong>Platforms</strong><strong>URL:</strong> <code>/admin/magic-ai/platforms</code></p></blockquote><p>The <strong>Platforms</strong> page is where you register the AI providers UnoPim is allowed to talk to. Without at least one active platform, every other Magic AI feature — wand icons, auto-translation, auto-enrichment, and the AI Agent Chat — stays switched off.</p><h2 id="what-is-a-platform" tabindex="-1">What is a Platform? <a class="header-anchor" href="#what-is-a-platform" aria-label="Permalink to &quot;What is a Platform?&quot;">​</a></h2><p>A <em>Platform</em> is one configured provider connection. It has three parts:</p><ol><li><strong>Provider</strong> — the company whose AI you want to use. UnoPim 3.0 supports <strong>OpenAI, Anthropic, Gemini, Groq, Ollama, xAI, Mistral, DeepSeek, Azure</strong>, and <strong>Custom</strong> (any OpenAI-compatible service).</li><li><strong>API key</strong> — the secret that authorises UnoPim to call that provider&#39;s API.</li><li><strong>Enabled models</strong> — which of the provider&#39;s models should be available inside UnoPim.</li></ol><p>You can register <strong>as many Platforms as you like</strong>. A common setup is one premium provider for content (e.g., OpenAI <code>gpt-4o</code>) and a cheaper or faster one for translation (e.g., Gemini <code>gemini-1.5-flash</code>). The Platforms page keeps them side by side; the <strong>Settings</strong> page decides which Platform handles which capability.</p><div class="tip custom-block"><p class="custom-block-title">Custom Provider</p><p>Need to call an OpenAI-compatible service that isn&#39;t on the preset list — for example a self-hosted gateway, a corporate proxy, or an alternative inference provider? Pick the <strong>Custom</strong> provider and enter its endpoint in the <strong>API URL</strong> field. For Custom providers the API URL is required, and UnoPim refuses addresses that point at restricted or internal network locations.</p></div><h2 id="first-time-setup-banner" tabindex="-1">First-time setup banner <a class="header-anchor" href="#first-time-setup-banner" aria-label="Permalink to &quot;First-time setup banner&quot;">​</a></h2><p>Until you register your first platform, the page shows a <strong>Get Started with Magic AI</strong> panel instead of the list. It walks you through the three steps — <em>Choose a provider</em>, <em>Enter your API key</em>, <em>Select models &amp; save</em> — and offers an <strong>Add Your First Platform</strong> button.</p><p>If platforms exist but none is marked as default, a warning appears: <em>&quot;No default platform is set. Please set one platform as default to enable AI features across the application.&quot;</em> Click the star on a platform row to clear it.</p><h2 id="what-does-this-page-do" tabindex="-1">What does this page do? <a class="header-anchor" href="#what-does-this-page-do" aria-label="Permalink to &quot;What does this page do?&quot;">​</a></h2><ul><li>Lists every Platform you&#39;ve registered, along with its status and models.</li><li>Lets you <strong>add</strong>, <strong>edit</strong>, <strong>enable/disable</strong>, <strong>delete</strong>, and <strong>set a default</strong> Platform.</li><li>Encrypts every API key on save — keys are never stored in plain text and are masked in the UI.</li></ul>',13)),o(a,{src:"/assets/3.0/images/magic-ai/ai-platforms.png",alt:"AI Platforms"}),t[1]||(t[1]=e('<h2 id="platforms-datagrid" tabindex="-1">Platforms datagrid <a class="header-anchor" href="#platforms-datagrid" aria-label="Permalink to &quot;Platforms datagrid&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Column</th><th>Description</th></tr></thead><tbody><tr><td><strong>Label</strong></td><td>The name you assigned to the platform configuration.</td></tr><tr><td><strong>Provider</strong></td><td>The AI provider (OpenAI, Anthropic, Gemini, Ollama, Groq, etc.).</td></tr><tr><td><strong>Models</strong></td><td>The models enabled for this platform.</td></tr><tr><td><strong>Default</strong></td><td>Whether this platform is the default (Yes/No).</td></tr><tr><td><strong>Status</strong></td><td>Enabled or Disabled.</td></tr><tr><td><strong>Created At</strong></td><td>Date the platform was added.</td></tr><tr><td><strong>Actions</strong></td><td>Star (set as default), Edit (pencil icon), Delete (trash icon).</td></tr></tbody></table><h2 id="adding-a-platform" tabindex="-1">Adding a Platform <a class="header-anchor" href="#adding-a-platform" aria-label="Permalink to &quot;Adding a Platform&quot;">​</a></h2><p>Click the <strong>Add Platform</strong> button in the top-right corner. A dialog opens with the following fields:</p><ol><li><strong>Provider</strong> — Select from the dropdown (OpenAI, Anthropic, Gemini, Groq, Ollama, xAI, Mistral, DeepSeek, Azure, or <strong>Custom</strong>).</li><li><strong>Label</strong> — A descriptive name such as <em>&quot;OpenAI Production&quot;</em> or <em>&quot;Gemini Translation&quot;</em>. This is what you&#39;ll see in the Settings dropdowns.</li><li><strong>API Key</strong> — Paste the key from your provider account. It&#39;s encrypted before it hits the database.</li><li><strong>API URL</strong> — Pre-filled with the provider&#39;s default endpoint. Edit it only if you use a proxy or a custom deployment. For the <strong>Custom</strong> provider this field is required.</li><li><strong>Deployment Name</strong> and <strong>API Version</strong> <em>(Azure only)</em> — extra fields shown when the provider is Azure.</li><li><strong>Models</strong> — As soon as you enter a valid API key, UnoPim contacts the provider and <strong>fetches the available models for you</strong>. Recommended models are pre-ticked; use the search box to find others, and tick every model you want to expose. If the fetch fails, you can still type model IDs by hand and click <strong>Add</strong>. Only the models you select here appear in the Text / Image / Translation / Agentic PIM dropdowns on the Settings page.</li><li><strong>Set as Default</strong> — Toggle to make this the default platform.</li><li><strong>Status</strong> — Toggle to enable or disable the platform.</li></ol>',5)),o(a,{src:"/assets/3.0/images/magic-ai/add-platform.png",alt:"Add Platform"}),t[2]||(t[2]=e(`<div class="tip custom-block"><p class="custom-block-title">TIP</p><p>API credentials are stored with encrypted credential storage for security. Your API keys are never stored in plain text.</p></div><h3 id="connection-testing-on-save" tabindex="-1">Connection testing on save <a class="header-anchor" href="#connection-testing-on-save" aria-label="Permalink to &quot;Connection testing on save&quot;">​</a></h3><p>You do not need to test the connection yourself. When you click <strong>Save</strong>, UnoPim first sends a small test request to the provider using the key, URL, and models you entered:</p><ul><li>The test uses a text-capable model from your list — image-only models are skipped, so they never cause a false failure. At least one text-capable model must be selected.</li><li>If the test fails, the platform is <strong>not saved</strong>, and a plain-language message explains what went wrong (invalid key, unreachable endpoint, model unavailable, etc.).</li><li>When you edit a platform without changing its API key, the test is skipped — your stored key stays untouched.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Because every save is verified against the provider first, a platform that appears in the list is known to have worked at the moment it was saved. If your provider key is rotated later, the next generation request will surface the error.</p></div><h2 id="platform-actions" tabindex="-1">Platform Actions <a class="header-anchor" href="#platform-actions" aria-label="Permalink to &quot;Platform Actions&quot;">​</a></h2><ul><li><strong>Star icon</strong> — Sets the platform as the <strong>default</strong>. Anywhere the Settings page shows <em>&quot;Use Default Platform&quot;</em>, it resolves to the starred platform. Only one can be the default at a time, and a disabled platform cannot be made the default.</li><li><strong>Pencil icon</strong> — Opens the edit dialog so you can update the label, rotate the API key, adjust the model list, or flip status.</li><li><strong>Trash icon</strong> — Deletes the platform configuration. Any feature that still points at this platform in Settings falls back to the default. You cannot delete the only default platform. Irreversible.</li></ul><h2 id="how-platform-selection-flows-into-features" tabindex="-1">How Platform selection flows into features <a class="header-anchor" href="#how-platform-selection-flows-into-features" aria-label="Permalink to &quot;How Platform selection flows into features&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Platforms (provider + key + models)</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>Settings (pick platform + model per feature)</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ├─► Text Generation ──► Wand icons on text fields</span></span>
<span class="line"><span>        ├─► Image Generation ──► Wand icons on image/gallery fields</span></span>
<span class="line"><span>        ├─► Translation ──────► Auto-translate on save + bulk command</span></span>
<span class="line"><span>        └─► Agentic PIM ──────► AI Agent Chat</span></span></code></pre></div><p>Every request — from a single field generation to a complex AI Agent plan — follows the <strong>Agentic PIM Pipeline</strong>:</p>`,10)),o(a,{src:"/assets/3.0/images/ai-agent/agentic-pim-pipeline.png",alt:"Agentic PIM Pipeline — 5-Step Workflow"}),t[3]||(t[3]=e('<h2 id="minimum-setup" tabindex="-1">Minimum setup <a class="header-anchor" href="#minimum-setup" aria-label="Permalink to &quot;Minimum setup&quot;">​</a></h2><p>To get any Magic AI feature working at all:</p><ol><li>Register at least <strong>one</strong> Platform.</li><li>Make sure it has at least <strong>one</strong> Model enabled.</li><li>Set its Status to <strong>Enabled</strong>.</li><li><strong>Star</strong> one Platform as the default.</li></ol><p>Once that&#39;s done, head to <strong>Magic AI → Settings</strong> to route each capability (Text / Image / Translation / Agentic PIM) to a Platform and Model of your choice.</p>',4))])}const P=s(l,[["render",d]]);export{f as __pageData,P as default};
